update pages set contenu = '{"sections":[]}'::jsonb where path = '/preuves/fdj/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"chiffres","chiffres":[{"valeur":"1 technicien","libelle":"un seul intervenant de maintenance expérimenté, affecté en continu au site, pas une personne différente à chaque visite"},{"valeur":"2025 et 2026","libelle":"la mission court sur deux exercices, sur le même périmètre"},{"valeur":"2 volets","libelle":"préventif et curatif tenus par le même technicien sur les lignes de production"},{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique ET comportemental"},{"valeur":"Renforcer l''équipe de maintenance interne","libelle":", sans la remplacer."},{"valeur":"Assurer la disponibilité des équipements industriels","libelle":", en continu."},{"valeur":"Réduire les temps d''arrêt","libelle":"et les délais d''intervention."},{"valeur":"Vous récupérez le préventif, pas seulement les urgences.","libelle":"Le technicien Migen tient la maintenance préventive et curative des lignes de production."},{"valeur":"Vous gagnez du temps sur le diagnostic.","libelle":"Les pannes sont identifiées sur place, par quelqu''un qui connaît déjà les installations."},{"valeur":"Vos équipes sont appuyées, pas remplacées.","libelle":"L''intervenant vient en soutien dans un contexte de forte activité."},{"valeur":"Vous démarrez sans formation initiale longue.","libelle":"Le technicien retenu a l''expérience des environnements industriels exigeants."},{"valeur":"Vous avez un interlocuteur côté Migen.","libelle":"Un référent technique assure le suivi et la coordination pendant toute la mission."},{"valeur":"L''intégration dans la structure existante","libelle":"s''est faite efficacement."},{"valeur":"L''expertise a été immédiate","libelle":"pour les équipes en place."},{"valeur":"La continuité de service","libelle":"a été tenue, sans rupture dans les interventions."}],"reponse":[{"texte":"La FDJ a posé trois objectifs, sans ambiguïté."},{"texte":"Le point commun des trois : ils demandent une présence permanente, pas un dépannage appelé quand la ligne est déjà à l''arrêt."},{"texte":"Un prestataire qui envoie une personne différente à chaque visite ne réduit aucun délai. Le temps gagné sur le déplacement se reperd sur le diagnostic."},{"texte":"C''est la raison du choix d''un intervenant unique, affecté au site dans la durée, qui finit par connaître les installations mieux que la documentation."},{"texte":"Ce que la mission a produit, tel que le dossier le documente."},{"texte":"> La collaboration avec la Française des Jeux illustre la capacité de Migen à intervenir dans des contextes industriels sensibles."},{"texte":"La mission se poursuit sur 2026, sur le même périmètre. Une présence reconduite sur deux exercices est le seul indicateur de satisfaction qui compte vraiment."},{"texte":"> [Demander un technicien en renfort](/contact/)"},{"texte":"Le **04 78 33 72 05** est ouvert du lundi au vendredi de 8h00 à 18h30, avec un rappel dans l''heure. Pour les nuits et les week-ends, l''astreinte 24/24 et 7/7 est disponible en option."},{"texte":"Un technicien qui arrive sur une ligne en production doit être bon tout de suite. C''est pour cela que nous n''en retenons que 10 %, après un entretien technique et un entretien comportemental."},{"texte":"> À lire aussi : [Étude de cas MERSEN : démarrage d''une ligne neuve](/preuves/mersen/)"}]}]'::jsonb) where path = '/preuves/fdj/';
